// Fast drop-in for makefun-site 1.0.0 (site-generator-speed-01-run-20261122).
// Rust/WASM build. run(input) returns exactly the output tree makefun-site 1.0.0's
// build returns for the case's site, byte for byte.
//
// The generator is compiled to WebAssembly (sitegen-rs, wasm32-unknown-unknown).
// The .wasm is embedded below as base64 (the repo push accepts UTF-8 files only)
// and instantiated synchronously at import. Input and output cross the WASM
// boundary in a compact binary format (length-prefixed UTF-8 strings), not JSON:
// JSON.stringify/parse of the 3-case set costs ~60ms, which alone would miss the
// native entries' range. The binary path keeps run() in the tens of ms.

const WASM_B64 = "";

const wasmBytes = Buffer.from(WASM_B64, 'base64');
const wasmModule = new WebAssembly.Module(wasmBytes);
const wasmInstance = new WebAssembly.Instance(wasmModule, {});
const { alloc, dealloc, build_bin, output_len, memory } = wasmInstance.exports;

const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

// ---------------------------------------------------------------- binary I/O

// A growable byte buffer for encoding the input.
let encBuf = new Uint8Array(1 << 20);
let encPos = 0;

function encEnsure(n) {
  if (encPos + n > encBuf.length) {
    let next = encBuf.length;
    while (encPos + n > next) next *= 2;
    const nb = new Uint8Array(next);
    nb.set(encBuf.subarray(0, encPos));
    encBuf = nb;
  }
}

function encU32(v) {
  encEnsure(4);
  encBuf[encPos] = v & 0xff;
  encBuf[encPos + 1] = (v >>> 8) & 0xff;
  encBuf[encPos + 2] = (v >>> 16) & 0xff;
  encBuf[encPos + 3] = (v >>> 24) & 0xff;
  encPos += 4;
}

function encF64(v) {
  encEnsure(8);
  new DataView(encBuf.buffer, encBuf.byteOffset + encPos, 8).setFloat64(0, v, true);
  encPos += 8;
}

function encStr(s) {
  // Write the UTF-8 byte length then the bytes.
  // encodeInto returns {read, written}; grow and retry if it did not fit.
  for (;;) {
    encEnsure(4 + s.length * 3 + 4);
    const r = textEncoder.encodeInto(s, encBuf.subarray(encPos + 4));
    if (r.read === s.length) {
      const len = r.written;
      encBuf[encPos] = len & 0xff;
      encBuf[encPos + 1] = (len >>> 8) & 0xff;
      encBuf[encPos + 2] = (len >>> 16) & 0xff;
      encBuf[encPos + 3] = (len >>> 24) & 0xff;
      encPos += 4 + len;
      return;
    }
    // Buffer too small for this string: grow a lot and retry.
    const nb = new Uint8Array(Math.max(encBuf.length * 2, encPos + 4 + s.length * 3 + 16));
    nb.set(encBuf.subarray(0, encPos));
    encBuf = nb;
  }
}

function encodeInput(input) {
  encPos = 0;
  encStr(input.site.title);
  encStr(input.site.base_url);
  encF64(input.site.per_page);
  encF64(input.site.recent);
  const tNames = Object.keys(input.templates);
  encU32(tNames.length);
  for (const name of tNames) {
    encStr(name);
    encStr(input.templates[name]);
  }
  encU32(input.files.length);
  for (const f of input.files) {
    encStr(f.path);
    encStr(f.content);
  }
  return encBuf.subarray(0, encPos);
}

function decodeOutput(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let pos = 0;
  const readU32 = () => {
    const v = view.getUint32(pos, true);
    pos += 4;
    return v;
  };
  const readStr = () => {
    const len = readU32();
    const s = textDecoder.decode(bytes.subarray(pos, pos + len));
    pos += len;
    return s;
  };
  const n = readU32();
  const out = {};
  for (let i = 0; i < n; i++) {
    const path = readStr();
    const text = readStr();
    out[path] = text;
  }
  return out;
}

// ---------------------------------------------------------------- run

export function run(input) {
  const bin = encodeInput(input);
  const ptr = alloc(bin.length);
  // Fresh view: the WASM memory may have grown since the last call.
  new Uint8Array(memory.buffer).set(bin, ptr);
  const outPtr = build_bin(ptr, bin.length);
  dealloc(ptr, bin.length);
  const outLen = output_len();
  const outBytes = new Uint8Array(memory.buffer).slice(outPtr, outPtr + outLen);
  dealloc(outPtr, outLen);
  return decodeOutput(outBytes);
}

export const REPORT_FILE = 'build-report.txt';
export const RESERVED = Object.freeze(['posts', 'tags', 'page']);
